('venue-clearview-sydney-harbour-cruises', 'clearview-sydney-harbour-cruises', 'Clearview Sydney Harbour Cruises', 'Venue', 'King Street Wharf, Sydney NSW', '32 The Promenade, King Street Wharf 5, Sydney NSW 2000', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', '(02) 8296 7353', 'hello@clearviewcruises.com.au', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Ceremony and reception or reception only: up to 260 seated or 440 cocktail. Intimate weddings up to 50 seated on the private mezzanine. Price (operator site, verify before booking): No base price published; package lengths 3h, 4h and 5.5h, 20% deposit. Ask for a quote.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["glass boat"], "sources": ["https://www.clearviewsydneyharbourcruises.com.au/wedding-venues", "https://www.clearviewsydneyharbourcruises.com.au/contact-us"], "flags": ["operator_is_australian_cruise_group", "no_byo"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
('venue-sydney-harbour-escapes', 'sydney-harbour-escapes', 'Sydney Harbour Escapes', 'Venue', 'Woolwich, Sydney NSW', '2C Margaret Street, Woolwich NSW 2111', 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', '(02) 9328 4748', NULL, 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Largest vessel (Starship Sydney): 440 at tables, 950 cocktail. Fleet runs from 10-guest to 950-guest boats. Price (operator site, verify before booking): Hourly charter, typically 4-hour minimum: from about $1,440 for the smallest boat to $10,000 for large superyachts; 50% deposit. Third-party operator figures, confirm before booking.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["fleet charter", "superyacht", "catamaran", "ferry"], "sources": ["https://www.sydneyharbourescapes.com.au/wedding-boat-charters", "https://boat.sydneyharbourescapes.com.au/contact-us/"], "flags": ["needs_contact_lookup", "email_missing_form_only", "charter_fleet_multiple_vessels"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking', 'needs_contact_lookup']),
('venue-all-occasion-cruises', 'all-occasion-cruises', 'All Occasion Cruises', 'Venue', 'Pyrmont, Sydney NSW', '5/11 Bank Street, Pyrmont NSW 2009', 'https://aocruises.com.au/wedding-cruise-sydney/', '(02) 9809 5499', 'info@aocruises.com.au', 'https://aocruises.com.au/wedding-cruise-sydney/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Largest vessel (Bella Vista): 280 seated, 750 cocktail. Smaller options from 36 guests (yachts) to 200 (Aussie Magic catamaran). Price (operator site, verify before booking): Hourly rates published per vessel, roughly $975 to $3,250 per hour; a 5-hour wedding package is offered, price on request.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["fleet charter", "catamaran", "superyacht"], "sources": ["https://aocruises.com.au/wedding-cruise-sydney/"], "flags": ["charter_fleet_multiple_vessels"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
