('venue-fantasea-cruising', 'fantasea-cruising', 'Fantasea Cruising', 'Venue', 'Darling Harbour, Sydney NSW', '2b Pier 26, Darling Harbour, Sydney NSW 2000', 'https://www.fantasea.com.au/wedding-reception/', '1800 326 822', 'charters@fantasea.com.au', 'https://www.fantasea.com.au/wedding-reception/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Largest vessel (Fantasea Catalina) holds up to 399 in total; seated/standing split not published. Price (operator site, verify before booking): No prices published; quote on request.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["fleet charter", "ferry"], "sources": ["https://www.fantasea.com.au/wedding-reception/", "https://www.fantasea.com.au/contact-us/"], "flags": ["capacity_split_not_published", "email_decoded_from_cloudflare", "charter_fleet_multiple_vessels", "second_departure_circular_quay_wharf_6"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
