('venue-sydney-harbour-yacht-charter', 'sydney-harbour-yacht-charter', 'Sydney Harbour Yacht Charter', 'Venue', 'Sydney Harbour, Sydney NSW', NULL, 'https://www.sydneyharbouryachtcharter.com.au/cruises/wedding-cruises/', '0409 224 739', 'info@shyc.com.au', 'https://www.sydneyharbouryachtcharter.com.au/cruises/wedding-cruises/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Largest named vessel (Ghost II) up to 110 guests; Legacy up to 80 standing or 24 seated. Most vessels are 36 guests or fewer.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["superyacht", "yacht", "overnight"], "sources": ["https://www.sydneyharbouryachtcharter.com.au/cruises/wedding-cruises/", "https://www.sydneyharbouryachtcharter.com.au/contact/"], "flags": ["needs_contact_lookup", "no_street_address", "verify_trading", "email_decoded_from_cloudflare", "charter_fleet_multiple_vessels"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking', 'needs_contact_lookup', 'verify_trading']),
