('venue-boatique-sydney-boat-hire', 'boatique-sydney-boat-hire', 'Boatique Sydney Boat Hire', 'Venue', 'King Street Wharf, Sydney NSW', NULL, 'https://boatiquesydneyboathire.com.au/wedding-boat-hire/', '0432 428 297', NULL, 'https://boatiquesydneyboathire.com.au/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Sixteen vessels from about 33 to 400 guests; seated/standing split not stated. Price (operator site, verify before booking): Hourly rates from $700 to about $3,300; 5-hour small-wedding reception tables from about $1,750 to $5,000. Catering from $45 per person; BYO is stated to cut costs. Couples must book their own celebrant.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["boat"], "special_subtype": ["fleet charter", "superyacht", "catamaran"], "sources": ["https://boatiquesydneyboathire.com.au/wedding-boat-hire/"], "flags": ["needs_contact_lookup", "email_missing_form_only", "no_street_address", "charter_broker"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking', 'needs_contact_lookup']),
