('venue-gosford-edogawa-commemorative-garden', 'gosford-edogawa-commemorative-garden', 'Gosford Edogawa Commemorative Garden', 'Venue', 'East Gosford, Central Coast NSW', '36 Webb Street, East Gosford NSW 2250', 'https://www.centralcoast.nsw.gov.au/recreation/planning-events/weddings', '02 4304 7550', 'gallery@centralcoast.nsw.gov.au', 'https://www.centralcoast.nsw.gov.au/recreation/planning-events/weddings', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Council says the outdoor space suits wedding parties of up to 150. Ceremonies are normally in the Koi Pavilion, which suits small intimate weddings; only a signing table and a maximum of 10 chairs are provided. Price (operator site, verify before booking): Not published on the council wedding page read.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["botanical"], "special_subtype": ["japanese garden", "public garden", "koi pavilion"], "sources": ["https://www.centralcoast.nsw.gov.au/recreation/planning-events/weddings"], "flags": ["address_from_search_result_verify", "price_not_published", "exclusive_use_not_guaranteed", "exclusive_caterer", "short_booking_1_5_hours"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
('venue-sea-life-sydney-aquarium', 'sea-life-sydney-aquarium', 'SEA LIFE Sydney Aquarium', 'Venue', 'Darling Harbour, Sydney CBD NSW', '1-5 Wheat Road, Darling Harbour, NSW 2000', 'https://www.visitsealife.com/sydney/tickets-passes/events-and-functions/private-events/weddings/', '02 9066 4095', 'merlin@bespokecatering.net.au', 'https://www.merlinvenues.com.au/your-event/private-events/weddings/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Per private-hire space: Dugong Island 200 cocktail / 160 sit-down; Day and Night on the Reef 280 cocktail / 85 sit-down; Jurassic Seas 100 cocktail / 50 sit-down. The page also says the whole venue holds around 1000 (unit labelled ''px''); the lower per-space figures are stored. The Day and Night on the Reef zone was noted as under renovation on the Merlin weddings page. Price (operator site, verify before booking): Not published on the official site; an event packages brochure PDF is linked but could not be read.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["zoo_aquarium"], "special_subtype": ["aquarium"], "sources": ["https://www.merlinvenues.com.au/your-event/private-events/weddings/", "https://www.merlinvenues.com.au/our-venues/sydney-nsw-venues/sea-life-sydney/", "https://www.merlinvenues.com.au/about-us/about-us/contact-us/", "https://www.visitsealife.com/sydney/tickets-passes/events-and-functions/private-events/weddings/", "https://www.visitsealife.com/sydney/plan-your-day/before-you-visit/directions-parking/getting-here/"], "flags": ["contact_is_merlin_shared_line", "capacity_conflict", "catering_partner_bespoke", "prices_not_published", "space_under_renovation"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
('venue-wild-life-sydney-zoo', 'wild-life-sydney-zoo', 'WILD LIFE Sydney Zoo', 'Venue', 'Darling Harbour, Sydney CBD NSW', '1-5 Wheat Road, Darling Harbour, Sydney NSW 2000', 'https://wildlifesydney.com.au/events/private-events/weddings', '02 9066 4095', 'merlin@bespokecatering.net.au', 'https://wildlifesydney.com.au/events/private-events/weddings', 'Unconventional venues import 2026-11-05', '2026-11-06', 'active', 'Koala Rooftop: 120 cocktail / 80 sit-down. Croc Deck: 80 cocktail / 50 sit-down. The venue page also states a whole-venue maximum of around 450 (labelled ''px''); the lower per-space figures are stored. Price (operator site, verify before booking): Not published on the official site.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["zoo_aquarium"], "special_subtype": ["zoo"], "sources": ["https://wildlifesydney.com.au/events/private-events/weddings", "https://wildlifesydney.com.au/", "https://www.merlinvenues.com.au/your-event/private-events/weddings/", "https://www.merlinvenues.com.au/our-venues/sydney-nsw-venues/wild-life-sydney-zoo/", "https://www.merlinvenues.com.au/about-us/about-us/contact-us/"], "flags": ["contact_is_merlin_shared_line", "capacity_conflict", "catering_partner_bespoke", "prices_not_published", "wedding_offer_verified_2026_11_06", "capacity_requires_reconfirmation"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
('venue-sydney-zoo', 'sydney-zoo', 'Sydney Zoo', 'Venue', 'Bungarribee, Western Sydney NSW', '700 Great Western Highway, Bungarribee NSW 2767', 'https://sydneyzoo.com/functions', '02 7202 2560', 'info@sydneyzoo.com', 'https://sydneyzoo.com/functions', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Largest space is Primate Boulevard: 350 seated / 750 cocktail. Lion Deck 200 seated / 400 cocktail; Boulevard Function Room 200 seated / 350 cocktail; Meerkat Wing 100 seated / 130 cocktail; Tiger Pool 90 seated / 70 cocktail (listed as given). Minimum 50 attendees; minimum spends apply to all spaces. Price (operator site, verify before booking): Not published; the terms say minimum spends apply to every space, prices include GST and holiday surcharges may apply.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["zoo_aquarium"], "special_subtype": ["zoo"], "sources": ["https://sydneyzoo.com/functions", "https://sydneyzoo.com/about/contact-us"], "flags": ["exclusive_caterer", "email_general_only", "prices_not_published", "wedding_subpages_not_loading", "capacity_conflict"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
