('venue-unexpected-guest-distillery', 'unexpected-guest-distillery', 'Unexpected Guest Distillery', 'Venue', 'Marrickville, Sydney NSW', '12 Cadogan Street, Marrickville NSW 2204', 'https://www.unexpectedguest.com.au/pages/private-events', NULL, 'venue@unexpectedguestgin.com', 'https://www.unexpectedguest.com.au/pages/private-events', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Capacity, ceremony rules and pricing not published; private hire is offered seven days a week.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["warehouse"], "special_subtype": ["distillery", "converted workshop"], "sources": ["https://www.unexpectedguest.com.au/pages/private-events", "https://www.unexpectedguest.com.au/pages/hire-the-kombi"], "flags": ["needs_contact_lookup", "phone_not_published", "postcode_inferred", "capacity_not_published", "email_is_bookings_over_12_people"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking', 'needs_contact_lookup']),
('venue-cockatoo-island-harbour-trust', 'cockatoo-island-harbour-trust', 'Cockatoo Island (Harbour Trust)', 'Venue', 'Cockatoo Island, Sydney Harbour NSW', 'Cockatoo Island (Wareamah), Sydney Harbour NSW', 'https://www.harbourtrust.gov.au/venue-hire/event-venues/', NULL, 'licensing@harbourtrust.gov.au', 'https://www.harbourtrust.gov.au/venue-hire/event-venues/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Ceremony on Biloela Lawn: 100 guests (FAQ; venue guide says 200 standing). Indoor halls: Turbine Shop 850 seated / 2,000 cocktail; Naval Store 150 seated / 200 cocktail. Wedding bookings on the lawn must be paired with a reception at one of the island''s two cafes. Price (operator site, verify before booking): Price on application. Ceremony hire is a 2-hour exclusive slot; no catering at the ceremony and only one celebratory drink per guest, supplied by the couple.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["warehouse"], "special_subtype": ["industrial heritage", "shipyard sheds", "island"], "sources": ["https://www.harbourtrust.gov.au/venue-hire/event-venues/", "https://www.harbourtrust.gov.au/media/ylmbekwv/faq-wedding-ceremony-location.pdf", "https://www.harbourtrust.gov.au/media/q0zbozc5/ht_venue-guide_cockatoo-island.pdf"], "flags": ["needs_contact_lookup", "phone_not_published", "no_street_address", "ferry_access", "ceremony_lawn_only", "fee_unreadable"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking', 'needs_contact_lookup']),
('venue-carriageworks', 'carriageworks', 'Carriageworks', 'Venue', 'Eveleigh, Sydney NSW', '245 Wilson Street, Eveleigh NSW 2015', 'https://carriageworks.com.au/venues/', '(02) 8571 9099', 'venues@carriageworks.com.au', 'https://carriageworks.com.au/venues/', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', 'Spaces range from Elston Room (150 banquet, 300 standing) and Bay 21 (250 banquet, 300 cocktail) to Bays 22-24 (1,500 banquet, 3,600 standing). Price (operator site, verify before booking): No prices published; quoted from a production schedule. Exclusive catering panel applies (BYO caterer not stated).', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["warehouse"], "special_subtype": ["industrial heritage", "railway workshops"], "sources": ["https://carriageworks.com.au/venues/", "https://carriageworks.com.au/wp-content/uploads/Carriageworks-Venue-Guide.pdf"], "flags": ["verify_weddings_accepted", "weddings_not_stated_on_site", "postcode_inferred", "exclusive_caterer_panel"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking']),
('venue-white-bay-cruise-terminal', 'white-bay-cruise-terminal', 'White Bay Cruise Terminal', 'Venue', 'Rozelle, Sydney NSW', NULL, 'https://www.portauthoritynsw.com.au/venues/white-bay-cruise-terminal-wbct', '(02) 9296 4999', 'enquiries@portauthoritynsw.com.au', 'https://www.portauthoritynsw.com.au/venues/white-bay-cruise-terminal-wbct', 'Unconventional venues import 2026-11-05', '2026-11-05', 'active', '3,500 square metre hall with 12m ceilings; page lists 1,250 banquet / 2,500 cocktail but also says use is currently capped at 500 people. Treat 500 as the limit until confirmed. Price (operator site, verify before booking): Rate card published as a PDF; not read. Hire is limited to non-ship days.', '{"source": "unconventional_venues_import", "imported": "2026-11-05", "special_category": ["warehouse"], "special_subtype": ["industrial waterfront", "cruise terminal"], "sources": ["https://www.portauthoritynsw.com.au/venues/white-bay-cruise-terminal-wbct", "https://www.portauthoritynsw.com.au/doing-business/venue-hire/white-bay-cruise-terminal-venue-hire"], "flags": ["verify_weddings_accepted", "weddings_not_stated_on_site", "no_street_address", "contact_is_general_port_authority", "capacity_conflict_500_vs_2500"]}'::jsonb, ARRAY['unconventional-import', 'verify-before-booking'])
