('venue-clearview-sydney-harbour-cruises', 'style_tags', '["boat", "glass boat", "unconventional", "harbour cruise", "on-water ceremony", "harbour views", "waterfront", "Sydney Harbour", "King Street Wharf", "glamorous", "all-inclusive", "no BYO"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-clearview-sydney-harbour-cruises', 'editorial_summary', '"A glass-roofed vessel that sails the harbour for the whole wedding, with the ceremony, canapés and dinner all on board. The in-house chef and crew run the day, and a smaller private upper level suits intimate groups. Alcohol must come from the boat (no BYO)."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-clearview-sydney-harbour-cruises', 'capacity_seated_max', '260'::jsonb, 'known', 0.8, 'primary_official', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Ceremony and reception or reception only: up to 260 seated or 440 cocktail. Intimate weddings up to 50 seated on the private mezzanine.'),
('venue-clearview-sydney-harbour-cruises', 'capacity_standing_max', '440'::jsonb, 'known', 0.8, 'primary_official', 'https://www.clearviewsydneyharbourcruises.com.au/wedding-venues', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Ceremony and reception or reception only: up to 260 seated or 440 cocktail. Intimate weddings up to 50 seated on the private mezzanine.'),
('venue-sydney-harbour-escapes', 'style_tags', '["boat", "superyacht", "yacht charter", "catamaran", "ferry", "unconventional", "harbour cruise", "on-water ceremony", "Sydney Harbour", "waterfront", "all sizes", "BYO on some boats", "wedding coordinator"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-escapes', 'editorial_summary', '"A charter company with eleven vessels from a 10-guest cruiser to a 950-guest function boat, including a classic ferry and a superyacht. Each wedding gets a coordinator, ceremonies on board are allowed, and some boats allow your own food and drink. Pick-ups are possible from many harbour wharves."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-escapes', 'capacity_seated_max', '440'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest vessel (Starship Sydney): 440 at tables, 950 cocktail. Fleet runs from 10-guest to 950-guest boats.'),
('venue-sydney-harbour-escapes', 'capacity_standing_max', '950'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourescapes.com.au/wedding-boat-charters', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest vessel (Starship Sydney): 440 at tables, 950 cocktail. Fleet runs from 10-guest to 950-guest boats.'),
('venue-all-occasion-cruises', 'style_tags', '["boat", "catamaran", "superyacht", "yacht charter", "unconventional", "harbour cruise", "sky deck ceremony", "Sydney Harbour", "waterfront", "glamorous", "all sizes"]'::jsonb, 'known', 0.8, 'primary_official', 'https://aocruises.com.au/wedding-cruise-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-all-occasion-cruises', 'editorial_summary', '"A harbour charter operator whose five-hour wedding package covers a vessel with wraparound decks, a sky deck for the ceremony and photos, and a private upper bar. Fleet choices range from 36-guest yachts to a 750-guest cocktail boat."'::jsonb, 'known', 0.8, 'primary_official', 'https://aocruises.com.au/wedding-cruise-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-all-occasion-cruises', 'capacity_seated_max', '280'::jsonb, 'known', 0.8, 'primary_official', 'https://aocruises.com.au/wedding-cruise-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest vessel (Bella Vista): 280 seated, 750 cocktail. Smaller options from 36 guests (yachts) to 200 (Aussie Magic catamaran).'),
('venue-all-occasion-cruises', 'capacity_standing_max', '750'::jsonb, 'known', 0.8, 'primary_official', 'https://aocruises.com.au/wedding-cruise-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest vessel (Bella Vista): 280 seated, 750 cocktail. Smaller options from 36 guests (yachts) to 200 (Aussie Magic catamaran).'),
('venue-sydney-harbour-tall-ships', 'style_tags', '["boat", "tall ship", "historic vessel", "timber ship", "unconventional", "romantic", "on-water ceremony", "Sydney Harbour", "The Rocks", "waterfront", "quirky", "LGBTQ+ friendly", "photos only option"]'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneytallships.com.au/cruise/weddings-ceremonies/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-tall-ships', 'editorial_summary', '"Traditional timber tall ships sailing from The Rocks, offered for ceremonies, receptions, guest transfers or a photos-only sail. A floating dance floor and live music or DJ are available. Fleet names, capacity and pricing are not published, so these need an enquiry."'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneytallships.com.au/cruise/weddings-ceremonies/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-fantasea-cruising', 'style_tags', '["boat", "ferry", "harbour cruise", "unconventional", "Sydney Harbour", "Darling Harbour", "Circular Quay", "waterfront", "flexible setup", "multiple wharf pick-ups"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.fantasea.com.au/wedding-reception/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-fantasea-cruising', 'editorial_summary', '"A Sydney Harbour charter fleet departing from Darling Harbour or Circular Quay, with vessels from about 30 up to 399 guests. Setup is flexible and pick-up is possible from several wharves; pricing is quoted per enquiry."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.fantasea.com.au/wedding-reception/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-prestige-harbour-cruises', 'style_tags', '["boat", "tall ship", "historic vessel", "classic ferry", "superyacht", "unconventional", "Sydney Harbour", "on-water ceremony", "waterfront", "all sizes", "boat marketplace"]'::jsonb, 'known', 0.8, 'primary_official', 'https://prestigeharbourcruises.com.au/wedding-ceremony/boat-hire', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-prestige-harbour-cruises', 'editorial_summary', '"A boat-hire marketplace listing dozens of Sydney vessels, including a square-rigged tall ship, a classic ferry and a 1960s timber cruiser alongside modern catamarans and superyachts. Useful for comparing options, but capacity and ceremony rules differ per vessel."'::jsonb, 'known', 0.8, 'primary_official', 'https://prestigeharbourcruises.com.au/wedding-ceremony/boat-hire', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-yacht-charter', 'style_tags', '["boat", "superyacht", "yacht", "luxury", "intimate", "unconventional", "on-water ceremony", "overnight charter", "Sydney Harbour", "Pittwater", "waterfront", "glamorous", "elopements"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbouryachtcharter.com.au/cruises/wedding-cruises/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-yacht-charter', 'editorial_summary', '"A superyacht and luxury yacht charter business offering intimate on-deck ceremonies, small receptions and overnight wedding charters, on Sydney Harbour and also Pittwater. Pricing is tailored per package and not published."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbouryachtcharter.com.au/cruises/wedding-cruises/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-exclusive', 'style_tags', '["boat", "superyacht", "luxury", "glass boat", "unconventional", "harbour cruise", "ceremony on deck", "Sydney Harbour", "waterfront", "glamorous", "BYO florist or stylist", "celebrant welcome"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourexclusive.com/charter-hire-events/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-exclusive', 'editorial_summary', '"A luxury yacht and function-boat charter company, established in 2010, handling ceremonies on deck, receptions or both. Couples can bring their own florist or stylist, and live music, DJs or fireworks can be added."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourexclusive.com/charter-hire-events/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-harbour-exclusive', 'capacity_standing_max', '950'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneyharbourexclusive.com/charter-hire-events/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Fleet capacity from about 20 to 950 people (The Starship); seated numbers per vessel not published.'),
('venue-sydney-yacht-club-boat-charter', 'style_tags', '["boat", "yacht", "catamaran", "luxury", "unconventional", "Sydney Harbour", "waterfront", "BYO", "BYO chef welcome", "all sizes", "CBD wharf pick-up"]'::jsonb, 'known', 0.8, 'primary_official', 'https://sydyachtclub.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-yacht-club-boat-charter', 'editorial_summary', '"A charter agency matching couples with luxury yachts, catamarans and function boats for groups of any size. Most boats allow BYO food and drink for a surcharge, and all central wharves are available for pick-up. Not a members'' club despite the name."'::jsonb, 'known', 0.8, 'primary_official', 'https://sydyachtclub.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-catamaran-hire', 'style_tags', '["boat", "catamaran", "intimate", "unconventional", "Sydney Harbour", "Opera House views", "Harbour Bridge views", "waterfront", "BYO", "small wedding", "relaxed"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneycatamaranhire.com.au/cruise-options/wedding-cruises/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-catamaran-hire', 'editorial_summary', '"Small catamarans for intimate harbour weddings of up to about 43 guests, with the Opera House and Harbour Bridge as the backdrop. Couples may bring their own food and drink or use partner caterers, and decorations can be arranged."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.sydneycatamaranhire.com.au/cruise-options/wedding-cruises/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-boatique-sydney-boat-hire', 'style_tags', '["boat", "catamaran", "superyacht", "unconventional", "Sydney Harbour", "on-water ceremony", "upper-deck ceremony", "waterfront", "BYO cake", "King Street Wharf", "all sizes"]'::jsonb, 'known', 0.8, 'primary_official', 'https://boatiquesydneyboathire.com.au/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-boatique-sydney-boat-hire', 'editorial_summary', '"A boat-hire booking service with sixteen Sydney vessels, mostly departing from King Street Wharf, where the ceremony usually happens on the upper deck. It publishes per-person cost guides, but the couple supplies their own registered celebrant."'::jsonb, 'known', 0.8, 'primary_official', 'https://boatiquesydneyboathire.com.au/wedding-boat-hire/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-eastcoast-sailing', 'style_tags', '["boat", "catamaran", "unconventional", "Sydney Harbour", "waterfront", "all sizes", "function boat", "relaxed"]'::jsonb, 'known', 0.8, 'primary_official', 'https://eastcoastsailing.com.au/catamaran-hire-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-eastcoast-sailing', 'editorial_summary', '"A large catamaran charter company with more than fifty boats for 12 to 240 guests, including function catamarans listed as suitable for weddings. Quotes come back with several matched vessels and ballpark pricing."'::jsonb, 'known', 0.8, 'primary_official', 'https://eastcoastsailing.com.au/catamaran-hire-sydney/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-blue-mountains-botanic-garden-mount-tomah', 'style_tags', '["botanical", "unconventional", "Blue Mountains", "mountain views", "rooftop garden", "Mount Tomah", "cool climate"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.botanicgardens.org.au/venues-and-lawns/all-venues-and-lawns/waratah-room', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-blue-mountains-botanic-garden-mount-tomah', 'editorial_summary', '"A cool-climate botanic garden high in the Blue Mountains offering several ceremony settings, a reception room with a kitchenette and, newly, exclusive hire of its rooftop lookout and visitor centre at sunset. Packages are tiered by group size, from intimate to around a hundred guests."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.botanicgardens.org.au/venues-and-lawns/all-venues-and-lawns/waratah-room', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-blue-mountains-botanic-garden-mount-tomah', 'capacity_seated_max', '60'::jsonb, 'known', 0.8, 'primary_official', 'https://www.botanicgardens.org.au/venues-and-lawns/all-venues-and-lawns/waratah-room', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Waratah Room seats 60; the Signature Botanic Wedding Package allows up to 100 standing. The Formal Garden page says up to 120 for hire while its package text says 100 standing or 60 seated, so the lower figures are stored. Viewing Deck package is up to 50; Camellia Garden and DeFerranti Pavilion up to 30.'),
('venue-blue-mountains-botanic-garden-mount-tomah', 'capacity_standing_max', '100'::jsonb, 'known', 0.8, 'primary_official', 'https://www.botanicgardens.org.au/venues-and-lawns/all-venues-and-lawns/waratah-room', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Waratah Room seats 60; the Signature Botanic Wedding Package allows up to 100 standing. The Formal Garden page says up to 120 for hire while its package text says 100 standing or 60 seated, so the lower figures are stored. Viewing Deck package is up to 50; Camellia Garden and DeFerranti Pavilion up to 30.'),
('venue-chinese-garden-of-friendship-darling-harbour', 'style_tags', '["botanical", "unconventional", "Chinese garden", "pagoda pavilions", "waterfront city", "Darling Harbour", "Sydney CBD"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.darlingharbour.com/precincts/chinese-garden/weddings,-functions,-filming-and-photography-at-th', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-chinese-garden-of-friendship-darling-harbour', 'editorial_summary', '"A classical Chinese garden with pavilions, bridges and reflective pools right beside Darling Harbour, bookable for daytime ceremonies or an exclusive evening function. Each pavilion has its own size, and catering is arranged through the on-site teahouse operator."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.darlingharbour.com/precincts/chinese-garden/weddings,-functions,-filming-and-photography-at-th', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
