('venue-wollongong-botanic-garden', 'style_tags', '["botanical", "unconventional", "rose garden", "gazebo", "Mount Keira", "Wollongong", "Illawarra"]'::jsonb, 'known', 0.8, 'primary_official', 'https://wollongongbotanicgarden.com.au/events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-wollongong-botanic-garden', 'editorial_summary', '"A council-run botanic garden at the foot of Mount Keira with several ceremony settings, including a rose garden with a gazebo and a red-desert arid collection. Couples hire a section by the hour for the ceremony, and wedding photos in the garden need no permit."'::jsonb, 'known', 0.8, 'primary_official', 'https://wollongongbotanicgarden.com.au/events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
