('venue-sea-life-sydney-aquarium', 'style_tags', '["aquarium", "unconventional", "underwater ceremony", "marine displays", "Darling Harbour", "Sydney CBD", "waterfront", "ceremony and reception"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.merlinvenues.com.au/your-event/private-events/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sea-life-sydney-aquarium', 'editorial_summary', '"Darling Harbour aquarium that offers weddings among its marine displays, with the Merlin venues page describing underwater-style ceremonies, sit-down banquets and cocktail receptions. Three private-hire zones suit different guest counts, from an intimate 50 seated up to a few hundred standing. Enquiries go through the shared Merlin events line and caterer."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.merlinvenues.com.au/your-event/private-events/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sea-life-sydney-aquarium', 'capacity_seated_max', '160'::jsonb, 'known', 0.8, 'primary_official', 'https://www.merlinvenues.com.au/your-event/private-events/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Per private-hire space: Dugong Island 200 cocktail / 160 sit-down; Day and Night on the Reef 280 cocktail / 85 sit-down; Jurassic Seas 100 cocktail / 50 sit-down. The page also says the whole venue holds around 1000 (unit labelled ''px''); the lower per-space figures are stored. The Day and Night on the Reef zone was noted as under renovation on the Merlin weddings page.'),
('venue-sea-life-sydney-aquarium', 'capacity_standing_max', '280'::jsonb, 'known', 0.8, 'primary_official', 'https://www.merlinvenues.com.au/your-event/private-events/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Per private-hire space: Dugong Island 200 cocktail / 160 sit-down; Day and Night on the Reef 280 cocktail / 85 sit-down; Jurassic Seas 100 cocktail / 50 sit-down. The page also says the whole venue holds around 1000 (unit labelled ''px''); the lower per-space figures are stored. The Day and Night on the Reef zone was noted as under renovation on the Merlin weddings page.'),
('venue-wild-life-sydney-zoo', 'style_tags', '["zoo", "wildlife", "unconventional", "koalas", "indoor wildlife", "Darling Harbour", "Sydney CBD", "waterfront", "rooftop"]'::jsonb, 'known', 0.8, 'primary_official', 'https://wildlifesydney.com.au/events/private-events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-06 00:00:00+00', NULL),
('venue-wild-life-sydney-zoo', 'editorial_summary', '"WILD LIFE Sydney Zoo''s current official wedding page confirms weddings in Darling Harbour, from small celebrations to larger events, with pre-set packages, tailored options and an experienced planning team. Bespoke Catering is the named catering partner and the published wedding enquiry address is merlin@bespokecatering.net.au. Capacity and price still need reconfirming because the current page does not publish them."'::jsonb, 'known', 0.8, 'primary_official', 'https://wildlifesydney.com.au/events/private-events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-06 00:00:00+00', NULL),
('venue-wild-life-sydney-zoo', 'capacity_seated_max', '80'::jsonb, 'known', 0.8, 'primary_official', 'https://wildlifesydney.com.au/events/private-events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-06 00:00:00+00', 'Koala Rooftop: 120 cocktail / 80 sit-down. Croc Deck: 80 cocktail / 50 sit-down. The venue page also states a whole-venue maximum of around 450 (labelled ''px''); the lower per-space figures are stored.'),
('venue-wild-life-sydney-zoo', 'capacity_standing_max', '120'::jsonb, 'known', 0.8, 'primary_official', 'https://wildlifesydney.com.au/events/private-events/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-06 00:00:00+00', 'Koala Rooftop: 120 cocktail / 80 sit-down. Croc Deck: 80 cocktail / 50 sit-down. The venue page also states a whole-venue maximum of around 450 (labelled ''px''); the lower per-space figures are stored.'),
('venue-sydney-zoo', 'style_tags', '["zoo", "wildlife", "unconventional", "lions", "tigers", "Bungarribee", "Eastern Creek", "Western Sydney", "free parking", "wheelchair accessible"]'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneyzoo.com/functions', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-zoo', 'editorial_summary', '"Western Sydney zoo that lists wedding receptions among its social functions, with spaces overlooking lion and tiger habitats. Space options range from a 90-seat Tiger Pool to the 350-seat Primate Boulevard. The zoo is the sole caterer, wedding packages include a security guard, and bridal photos in the grounds are limited to one hour."'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneyzoo.com/functions', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-sydney-zoo', 'capacity_seated_max', '350'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneyzoo.com/functions', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest space is Primate Boulevard: 350 seated / 750 cocktail. Lion Deck 200 seated / 400 cocktail; Boulevard Function Room 200 seated / 350 cocktail; Meerkat Wing 100 seated / 130 cocktail; Tiger Pool 90 seated / 70 cocktail (listed as given). Minimum 50 attendees; minimum spends apply to all spaces.'),
('venue-sydney-zoo', 'capacity_standing_max', '750'::jsonb, 'known', 0.8, 'primary_official', 'https://sydneyzoo.com/functions', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Largest space is Primate Boulevard: 350 seated / 750 cocktail. Lion Deck 200 seated / 400 cocktail; Boulevard Function Room 200 seated / 350 cocktail; Meerkat Wing 100 seated / 130 cocktail; Tiger Pool 90 seated / 70 cocktail (listed as given). Minimum 50 attendees; minimum spends apply to all spaces.'),
('venue-australian-reptile-park', 'style_tags', '["wildlife park", "reptiles", "unconventional", "outdoor ceremony", "bush setting", "Somersby", "Central Coast", "animal encounters", "undercover reception"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.reptilepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-australian-reptile-park', 'editorial_summary', '"A Central Coast wildlife park offering outdoor ceremonies among eucalypts and lawns, with undercover options for wet weather. The reception space is covered and set up for dining and dancing, and couples can add animal photos, private reptile shows or encounters. A functions team handles planning and supplier suggestions."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.reptilepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-taronga-western-plains-zoo', 'style_tags', '["zoo", "wildlife", "safari", "unconventional", "lake views", "Dubbo", "Central West", "regional NSW", "elopement", "accommodation on site", "ceremony and reception"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.taronga.org.au/dubbo-zoo/function-venue-hire/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-taronga-western-plains-zoo', 'editorial_summary', '"A large open-range zoo in Dubbo that hosts weddings with several ceremony locations in its grounds and receptions at the lakeside Savannah Function Centre. Three packages are offered: reception only, ceremony and reception, and a small elopement. Guests can stay on site at Zoofari Lodge or the Savannah Cabins."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.taronga.org.au/dubbo-zoo/function-venue-hire/weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-featherdale-wildlife-park', 'style_tags', '["wildlife park", "unconventional", "Australian native animals", "Doonside", "Blacktown", "Western Sydney", "daytime events", "private hire"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.featherdale.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-featherdale-wildlife-park', 'editorial_summary', '"Native-animal park in western Sydney that rents out its Drover''s Hut, courtyard and picnic areas for private functions and exclusive-hire days. The events page names corporate events, birthdays and celebrations but not weddings, so a wedding enquiry would need to be confirmed. Daytime events only, with acoustic music indoors."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.featherdale.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-featherdale-wildlife-park', 'capacity_seated_max', '90'::jsonb, 'known', 0.8, 'primary_official', 'https://www.featherdale.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'The Drover''s Hut seats 90 inside or outside and takes 110 grazing style. Keeper''s Courtyard seats up to 60 at picnic tables; two picnic areas seat 50 each. Events are daytime only and only acoustic music is allowed in the Drover''s Hut.'),
('venue-featherdale-wildlife-park', 'capacity_standing_max', '110'::jsonb, 'known', 0.8, 'primary_official', 'https://www.featherdale.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'The Drover''s Hut seats 90 inside or outside and takes 110 grazing style. Keeper''s Courtyard seats up to 60 at picnic tables; two picnic areas seat 50 each. Events are daytime only and only acoustic music is allowed in the Drover''s Hut.'),
('venue-mogo-wildlife-park', 'style_tags', '["zoo", "wildlife", "unconventional", "exclusive hire", "Mogo", "South Coast", "Batemans Bay", "regional NSW", "marquee"]'::jsonb, 'known', 0.8, 'primary_official', 'https://mogowildlifepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-mogo-wildlife-park', 'editorial_summary', '"South Coast zoo that offers private function spaces, from a terrace and deck to a 100-seat events centre and a lawn that can take marquees. Couples can book the whole park for an exclusive-hire day. The events page does not name weddings, so confirm ceremonies and receptions are accepted."'::jsonb, 'known', 0.8, 'primary_official', 'https://mogowildlifepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-mogo-wildlife-park', 'capacity_seated_max', '100'::jsonb, 'known', 0.8, 'primary_official', 'https://mogowildlifepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Function and Events Centre (by Primate Island): 100 seated indoors or cocktail style; up to 300 using the outdoor verandahs and picnic areas. Grassy Glade up to 200 with marquees/tables (weather dependent). Main Cafe terrace 50 seated or about 100 standing; Tiger Deck 50. Whole-park exclusive hire is available.'),
('venue-mogo-wildlife-park', 'capacity_standing_max', '300'::jsonb, 'known', 0.8, 'primary_official', 'https://mogowildlifepark.com.au/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Function and Events Centre (by Primate Island): 100 seated indoors or cocktail style; up to 300 using the outdoor verandahs and picnic areas. Grassy Glade up to 200 with marquees/tables (weather dependent). Main Cafe terrace 50 seated or about 100 standing; Tiger Deck 50. Whole-park exclusive hire is available.'),
('venue-james-theatre-dungog', 'style_tags', '["cinema", "unconventional", "dungog", "hunter region", "regional nsw", "heritage", "oldest cinema", "spanish mission", "community run", "dance floor", "garden"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.jamestheatre.com.au/hire', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-james-theatre-dungog', 'editorial_summary', '"A volunteer-run heritage picture house in Dungog, billed as the oldest purpose-built cinema still operating in Australia, with a Spanish Mission facade and a stage and supper room from the 1930s. It can be hired for weddings and parties, with a dance floor, a modern kitchen area and an outdoor barbecue garden alongside the cinema seating. A good rustic-heritage option for couples happy to travel to the Hunter."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.jamestheatre.com.au/hire', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-the-roxy-theatre-bingara', 'style_tags', '["cinema", "unconventional", "bingara", "regional nsw", "north west nsw", "art deco", "1936", "heritage listed", "greek cafe", "council run"]'::jsonb, 'known', 0.8, 'primary_official', 'https://visitgwydir.com.au/the-roxy-theatre/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-the-roxy-theatre-bingara', 'editorial_summary', '"A 1936 Art Deco picture palace on Bingara''s main street, restored and reopened in 2004 and now state heritage listed. The council''s page says it works as a function centre for events from birthdays and weddings to conferences, alongside its cinema and performing-arts program. Wedding specifics such as ceremony spaces and numbers are not spelled out, so an enquiry is needed."'::jsonb, 'known', 0.8, 'primary_official', 'https://visitgwydir.com.au/the-roxy-theatre/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
