('venue-elizabeth-bay-house', 'style_tags', '["museum", "historic house", "colonial", "harbour views", "domed saloon", "sweeping staircase", "intimate", "small wedding", "Elizabeth Bay", "heritage", "unconventional", "ceremony and reception", "10:30pm finish"]'::jsonb, 'known', 0.8, 'primary_official', 'https://mhnsw.au/venue-hire/elizabeth-bay-house/content/elizabeth-bay-house-weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-elizabeth-bay-house', 'editorial_summary', '"An 1830s harbourside house museum with a domed saloon and a sweeping staircase, hosting small ceremonies and receptions of up to about 100 guests. Strict heritage rules apply: no BYO alcohol, no open flames, approved caterers only, and a finish by 10:30pm."'::jsonb, 'known', 0.8, 'primary_official', 'https://mhnsw.au/venue-hire/elizabeth-bay-house/content/elizabeth-bay-house-weddings/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
