('venue-penrith-regional-gallery-and-the-lewers-bequest', 'style_tags', '["gallery", "art gallery", "sculpture garden", "heritage gardens", "riverside", "Nepean River", "garden ceremony", "canopy reception", "Penrith", "Western Sydney", "intimate", "romantic", "exclusive caterer", "unconventional"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.penrithregionalgallery.com.au/hire-our-venue/weddings-special-events/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-penrith-regional-gallery-and-the-lewers-bequest', 'editorial_summary', '"Two acres of heritage gardens beside the Nepean River, filled with sculpture and mosaics, with a garden ceremony and a covered sandstone-and-cedar canopy reception beside a regional gallery. Private evening hire for 40 to about 100 guests, with the on-site cafe as the required caterer."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.penrithregionalgallery.com.au/hire-our-venue/weddings-special-events/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-penrith-regional-gallery-and-the-lewers-bequest', 'capacity_seated_max', '100'::jsonb, 'known', 0.8, 'primary_official', 'https://www.penrithregionalgallery.com.au/hire-our-venue/weddings-special-events/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', '100 sit-down or 120 canapes; minimum 40 guests. Private hire 4:00pm-10:30pm with a 3-hour minimum; bar closes about 9:30pm.'),
('venue-penrith-regional-gallery-and-the-lewers-bequest', 'capacity_standing_max', '120'::jsonb, 'known', 0.8, 'primary_official', 'https://www.penrithregionalgallery.com.au/hire-our-venue/weddings-special-events/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', '100 sit-down or 120 canapes; minimum 40 guests. Private hire 4:00pm-10:30pm with a 3-hour minimum; bar closes about 9:30pm.'),
('venue-campbelltown-arts-centre', 'style_tags', '["gallery", "arts centre", "contemporary art", "sculpture gardens", "performance studio", "air conditioned", "daytime wedding", "Campbelltown", "Macarthur", "Western Sydney", "unconventional", "tiered seating"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.campbelltown.nsw.gov.au/Services-and-Facilities/Facilities-for-Hire/Campbelltown-Arts-Centre-Performance-Studio', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-campbelltown-arts-centre', 'editorial_summary', '"A council-run contemporary arts centre whose air-conditioned performance studio and sculpture gardens can be hired for functions, with the studio page naming weddings. Daytime hire by default, so it suits a lunch or afternoon celebration; ceremony and catering rules are not published."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.campbelltown.nsw.gov.au/Services-and-Facilities/Facilities-for-Hire/Campbelltown-Arts-Centre-Performance-Studio', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-campbelltown-arts-centre', 'capacity_seated_max', '180'::jsonb, 'known', 0.8, 'primary_official', 'https://www.campbelltown.nsw.gov.au/Services-and-Facilities/Facilities-for-Hire/Campbelltown-Arts-Centre-Performance-Studio', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Performance Studio: up to 180 seated (tiered bank lists 200 seats) / 350 standing. Sculpture Gardens hireable by the half or full day, capacity not stated. Hire window 8:30am-4:30pm unless extended for a fee.'),
('venue-campbelltown-arts-centre', 'capacity_standing_max', '350'::jsonb, 'known', 0.8, 'primary_official', 'https://www.campbelltown.nsw.gov.au/Services-and-Facilities/Facilities-for-Hire/Campbelltown-Arts-Centre-Performance-Studio', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Performance Studio: up to 180 seated (tiered bank lists 200 seats) / 350 standing. Sculpture Gardens hireable by the half or full day, capacity not stated. Hire window 8:30am-4:30pm unless extended for a fee.'),
('venue-barnet-long-room-at-customs-house', 'style_tags', '["library building", "Customs House", "heritage", "Circular Quay", "harbour views", "function room", "stage", "exclusive caterer", "CBD", "historic", "unconventional"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.cityofsydney.nsw.gov.au/hireable-indoor-spaces/barnet-long-room-customs-house', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-barnet-long-room-at-customs-house', 'editorial_summary', '"A first-floor function room in the heritage Customs House above Circular Quay, listed by the City of Sydney with weddings among permitted uses. It has permanent staging at each end and harbour views, but all catering goes through the council''s nominated caterer. Ceremony rules are not stated."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.cityofsydney.nsw.gov.au/hireable-indoor-spaces/barnet-long-room-customs-house', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-3danks', 'style_tags', '["warehouse", "industrial", "blank canvas", "exposed beams", "high ceilings", "mezzanine", "ceremony and reception", "BYO celebrant", "own caterer", "urban", "Waterloo", "dry hire", "full kitchen"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.3danks.com.au/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-3danks', 'editorial_summary', '"An 890 square metre open-plan warehouse complex whose main hall has a tall ceiling and a mezzanine, hired as a blank canvas for ceremony and reception in one place. Couples bring their own caterer, styling and music, with a full kitchen on site. Amplified music has to stop by 9:30pm."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.3danks.com.au/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-3danks', 'capacity_seated_max', '270'::jsonb, 'known', 0.8, 'primary_official', 'https://www.3danks.com.au/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Whole venue: 270 seated dinner, 400 standing cocktail, 342 theatre-style ceremony seats. Amplified music ends 9:30pm; bump-out can continue later.'),
('venue-3danks', 'capacity_standing_max', '400'::jsonb, 'known', 0.8, 'primary_official', 'https://www.3danks.com.au/weddings', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', 'Whole venue: 270 seated dinner, 400 standing cocktail, 342 theatre-style ceremony seats. Amplified music ends 9:30pm; bump-out can continue later.'),
('venue-nauti-studios-sydney', 'style_tags', '["warehouse", "industrial", "creative studio", "blank canvas", "greenhouse", "white brick", "BYO", "own caterer", "outdoor deck", "affordable", "non-profit", "Inner West", "Glebe", "intimate", "drive-in access"]'::jsonb, 'known', 0.8, 'primary_official', 'https://nautistudios.com.au/wedding-reception-hire-sydney-glebe', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-nauti-studios-sydney', 'editorial_summary', '"A converted industrial studio with a large concrete-floored hall and a smaller light-filled greenhouse room, plus an outdoor deck, run as a non-profit. Outside caterers and BYO food and drink are welcome, so it suits a hands-on, budget-conscious wedding of up to about 180 guests."'::jsonb, 'known', 0.8, 'primary_official', 'https://nautistudios.com.au/wedding-reception-hire-sydney-glebe', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-unexpected-guest-distillery', 'style_tags', '["distillery", "gin bar", "converted workshop", "industrial", "quirky", "unconventional", "Marrickville", "Inner West", "cocktails", "intimate", "relaxed", "copper still", "engagement party", "mobile Kombi bar"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.unexpectedguest.com.au/pages/private-events', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-unexpected-guest-distillery', 'editorial_summary', '"A gin distillery and bar in a reimagined mechanic''s workshop, with a terrazzo bar and copper still, taking private hire for weddings, engagements and masterclasses. A vintage Kombi mobile bar can also travel to other NSW wedding venues. Capacity and prices are quote-only."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.unexpectedguest.com.au/pages/private-events', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-cockatoo-island-harbour-trust', 'style_tags', '["industrial heritage", "shipyard", "island", "ferry access", "harbour views", "unconventional", "raw", "steel and sandstone", "outdoor ceremony", "Sydney Harbour", "convict heritage", "photogenic", "dry hire"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.harbourtrust.gov.au/venue-hire/event-venues/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-cockatoo-island-harbour-trust', 'editorial_summary', '"A heritage island in the harbour with old shipyard workshops, cranes and sandstone. Wedding ceremonies are held on Biloela Lawn for up to about 100 guests, with a reception at one of the island''s cafes, while the large industrial halls are hired as dry spaces for bigger events. Reached by ferry, with no street address."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.harbourtrust.gov.au/venue-hire/event-venues/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-carriageworks', 'style_tags', '["industrial heritage", "railway workshops", "warehouse", "exposed brick", "high ceilings", "polished concrete", "arts precinct", "large guest list", "Eveleigh", "raw", "blank canvas", "catering panel"]'::jsonb, 'known', 0.8, 'primary_official', 'https://carriageworks.com.au/venues/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-carriageworks', 'editorial_summary', '"A big 19th-century railway workshop complex turned arts centre, with raw brick bays, apex ceilings and polished concrete halls that couples have used for weddings and receptions. Best for large guest lists and heavy styling; the venue works from an exclusive caterer panel and quotes each event individually."'::jsonb, 'known', 0.8, 'primary_official', 'https://carriageworks.com.au/venues/', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-white-bay-cruise-terminal', 'style_tags', '["industrial", "waterfront", "cruise terminal", "high ceilings", "concrete", "blank canvas", "large guest list", "city skyline views", "Rozelle", "urban", "car park on site"]'::jsonb, 'known', 0.8, 'primary_official', 'https://www.portauthoritynsw.com.au/venues/white-bay-cruise-terminal-wbct', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL),
('venue-white-bay-cruise-terminal', 'editorial_summary', '"A vast industrial-chic waterfront terminal with 12 metre ceilings and city views, hired as an empty shell for galas and large events and, per wedding guides, occasionally weddings. Couples bring in all catering, styling and production. Current hire is capped at 500 people."'::jsonb, 'known', 0.8, 'primary_official', 'https://www.portauthoritynsw.com.au/venues/white-bay-cruise-terminal-wbct', 'Unconventional venues import 2026-11-05', TIMESTAMPTZ '2026-11-05 00:00:00+00', NULL)
